        ,(SELECT COALESCE(MAX(addition_key), 0) FROM MSF_REQUEST_ADDITION_TEMP WHERE REQUEST_KEY=#{item.requestKey}) + #{additionIdx} + 1
        ,#{item.additionId}
        ,#{item.additionNm}
        ,#{item.rantal}
    )

